import * as React from "react";
import { cn } from "@/lib/utils";

export interface ToggleProps {
  /** Optional label rendered to the left of the switch. */
  label?: React.ReactNode;
  /** Optional helper text rendered below the label. */
  description?: React.ReactNode;
  checked: boolean;
  onChange: (checked: boolean) => void;
  disabled?: boolean;
  className?: string;
  /** Inline styles for the root element. */
  style?: React.CSSProperties;
  /** Accessible label when no visible `label` is provided. */
  "aria-label"?: string;
}

/**
 * Switch-style boolean toggle. When `label` is provided, the whole row reads
 * as `[label]  [switch]`; without a label, just the switch renders (use the
 * `aria-label` prop in that case for accessibility).
 */
const Toggle = React.forwardRef<HTMLButtonElement, ToggleProps>(
  ({ label, description, checked, onChange, disabled, className, ...rest }, ref) => {
    const handleToggle = () => {
      if (!disabled) onChange(!checked);
    };

    const switchEl = (
      <button
        ref={ref}
        type="button"
        role="switch"
        aria-checked={checked}
        onClick={handleToggle}
        disabled={disabled}
        className={cn(
          "relative inline-flex h-6 w-11 shrink-0 rounded-full transition-colors",
          "wj-focus-ring",
          "disabled:cursor-not-allowed disabled:opacity-50",
          // The track's tone follows the theme when off and is an accent fill
          // when on, so the bevel it takes switches with it.
          checked
            ? "bg-[var(--color-accent-500)] shadow-bevel-dark"
            : "bg-[var(--color-warm-200)] shadow-bevel dark:bg-[var(--color-neutral-700)]",
          !label && className,
        )}
        {...(!label ? rest : {})}
      >
        <span
          aria-hidden
          data-on={checked}
          // Position, size and travel live in .wj-toggle-knob: it drives both
          // edges independently to get the squash-and-stretch, which a
          // transform cannot express. White in both themes, so its edge is
          // always the light-surface one.
          className="wj-toggle-knob bg-white shadow-md-bevel-light"
        />
      </button>
    );

    if (!label) return switchEl;

    return (
      <label
        className={cn(
          "flex items-center justify-between gap-3 cursor-pointer",
          disabled && "cursor-not-allowed opacity-50",
          className,
        )}
      >
        <span className="flex flex-col gap-0.5 min-w-0">
          {/*
            `text-sm` on secondary, matching every other labelled row: an Input's
            label, a Select's, and the label a caller puts beside a Slider or a
            SegmentedControl. This was `text-xs` on muted, which made a toggle's
            title the smallest and faintest text in a settings card while being
            the primary thing in its row -- visibly undersized as soon as one sat
            next to any other labelled control.

            The description keeps the smaller muted treatment, so the pair still
            reads as title-then-hint rather than two lines of equal weight.
          */}
          <span className="text-sm text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]">
            {label}
          </span>
          {description && (
            <span className="text-[11px] leading-snug text-[var(--color-text-muted-light)]/80 dark:text-[var(--color-text-muted-dark)]/80">
              {description}
            </span>
          )}
        </span>
        {switchEl}
      </label>
    );
  },
);
Toggle.displayName = "Toggle";

export { Toggle };
